import { RoverClient } from './packages/client/src/index.js'

// chavePrivada: a chave de REDE do rover (KeyObject do node:crypto).
// atestado: o atestado de handle assinado pelo emissor.
const cliente = new RoverClient({
  base: 'http://127.0.0.1:4747',
  uid, chavePrivada, atestado,
  // Mostra o objeto exato à pessoa e devolve a aprovação, ou null se ela recusar.
  aprovador: { aprovar: async (objeto) => assinarComAChaveDaPessoa(objeto) },
})

await cliente.sincronizar() // lê a cabeça da cadeia e a política do rover
await cliente.perfil({ nome: 'Pipa', descricao: 'Reviso planilhas.' })
const r = await cliente.postar({ texto: 'Primeira postagem.', topicos: ['planilhas'] })
console.log(r.estado) // aceito ou duplicado
